<script setup lang="ts">defineProps<{open:boolean}>();const emit=defineEmits<{close:[]}>();const {schoolOptions,schoolId}=useSchool();const {links}=useNavigation();const route=useRoute();watch(()=>route.path,()=>emit('close'))</script><template><aside :class="open?'translate-x-0':'-translate-x-full lg:translate-x-0'" class="fixed inset-y-0 left-0 z-40 flex w-64 flex-col border-r border-[var(--border)] bg-[var(--surface)] transition-transform lg:sticky lg:top-0 lg:h-screen"><div class="flex h-20 items-center justify-between border-b border-[var(--border)] px-5"><NuxtLink to="/dashboard" aria-label="School Sports Tracker home" class="flex min-w-0 flex-1 items-center justify-center"><img src="/logo.png" alt="School Sports Tracker" class="h-14 w-full max-w-[190px] object-contain object-center" /></NuxtLink><button class="lg:hidden" aria-label="Close menu" @click="emit('close')">✕</button></div><div v-if="schoolOptions.length" class="px-4 pt-5"><label for="school-select" class="mb-2 block text-xs font-semibold text-[var(--muted)]">ACTIVE SCHOOL</label><select id="school-select" v-model="schoolId" class="w-full rounded-xl border border-[var(--border)] bg-[var(--panel)] p-3 text-sm"><option v-for="s in schoolOptions" :key="s.id" :value="s.id">{{s.name}}</option></select></div><nav class="mt-5 flex-1 space-y-1 overflow-y-auto px-3" aria-label="Workspace navigation"><NuxtLink v-for="link in links" :key="link.to" :to="link.to" class="block rounded-xl px-4 py-3 text-sm font-semibold hover:bg-[var(--panel)]" :class="route.path===link.to.split('?')[0]?'bg-[var(--panel)] text-blue-600':''">{{link.label}}</NuxtLink></nav><button class="m-4 rounded-xl border border-[var(--border)] p-3 text-left text-sm" @click="useSupabaseClient().auth.signOut().then(()=>navigateTo('/login'))">Sign out</button></aside></template>